  1→package cli
  2→
  3→import (
  4→	"bufio"
  5→	"encoding/json"
  6→	"fmt"
  7→	"io"
  8→	"os"
  9→	"sort"
 10→	"strconv"
 11→	"strings"
 12→	"time"
 13→)
 14→
 15→// perfStep represents a single timed step within a perf span.
 16→// Group steps (from nested spans) have SubSteps with 0-based iteration numbering.
 17→type perfStep struct {
 18→	Name       string
 19→	DurationMs int64
 20→	Error      bool
 21→	SubSteps   []perfStep
 22→}
 23→
 24→// perfEntry represents a parsed performance trace log entry.
 25→type perfEntry struct {
 26→	Op         string
 27→	DurationMs int64
 28→	Error      bool
 29→	Time       time.Time
 30→	Steps      []perfStep
 31→}
 32→
 33→// parsePerfEntry parses a JSON log line into a perfEntry.
 34→// Returns nil if the line is not valid JSON or is not a perf entry (msg != "perf").
 35→func parsePerfEntry(line string) *perfEntry {
 36→	var raw map[string]json.RawMessage
 37→	if err := json.Unmarshal([]byte(line), &raw); err != nil {
 38→		return nil
 39→	}
 40→
 41→	// Check that msg == "perf"
 42→	var msg string
 43→	if msgRaw, ok := raw["msg"]; !ok {
 44→		return nil
 45→	} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
 46→		return nil
 47→	}
 48→
 49→	entry := &perfEntry{}
 50→
 51→	// Extract op
 52→	if opRaw, ok := raw["op"]; ok {
 53→		if err := json.Unmarshal(opRaw, &entry.Op); err != nil {
 54→			return nil
 55→		}
 56→	}
 57→
 58→	// Extract duration_ms
 59→	if dRaw, ok := raw["duration_ms"]; ok {
 60→		if err := json.Unmarshal(dRaw, &entry.DurationMs); err != nil {
 61→			return nil
 62→		}
 63→	}
 64→
 65→	// Extract error flag
 66→	if errRaw, ok := raw["error"]; ok {
 67→		if err := json.Unmarshal(errRaw, &entry.Error); err != nil {
 68→			return nil
 69→		}
 70→	}
 71→
 72→	// Extract time
 73→	if tRaw, ok := raw["time"]; ok {
 74→		var ts string
 75→		if err := json.Unmarshal(tRaw, &ts); err == nil {
 76→			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
 77→				entry.Time = parsed
 78→			}
 79→		}
 80→	}
 81→
 82→	// Extract steps by finding keys matching "steps.*_ms"
 83→	stepDurations := make(map[string]int64)
 84→	stepErrors := make(map[string]bool)
 85→
 86→	for key, val := range raw {
 87→		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
 88→			name := strings.TrimPrefix(key, "steps.")
 89→			name = strings.TrimSuffix(name, "_ms")
 90→
 91→			var ms int64
 92→			if err := json.Unmarshal(val, &ms); err == nil {
 93→				stepDurations[name] = ms
 94→			}
 95→		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
 96→			name := strings.TrimPrefix(key, "steps.")
 97→			name = strings.TrimSuffix(name, "_err")
 98→
 99→			var errFlag bool
100→			if err := json.Unmarshal(val, &errFlag); err == nil {
101→				stepErrors[name] = errFlag
102→			}
103→		}
104→	}
105→
106→	// Separate parent steps from sub-steps.
107→	// A key like "foo.0" is a sub-step of "foo" if "foo" also exists as a parent
108→	// and the last segment is a non-negative integer.
109→	subStepDurations := make(map[string]map[int]int64) // parent -> index -> ms
110→	subStepErrors := make(map[string]map[int]bool)     // parent -> index -> err
111→	parentStepDurations := make(map[string]int64)
112→	parentStepErrors := make(map[string]bool)
113→
114→	for name, ms := range stepDurations {
115→		if parent, idx, ok := parseSubStepKey(name, stepDurations); ok {
116→			if subStepDurations[parent] == nil {
117→				subStepDurations[parent] = make(map[int]int64)
118→			}
119→			subStepDurations[parent][idx] = ms
120→			if stepErrors[name] {
121→				if subStepErrors[parent] == nil {
122→					subStepErrors[parent] = make(map[int]bool)
123→				}
124→				subStepErrors[parent][idx] = true
125→			}
126→		} else {
127→			parentStepDurations[name] = ms
128→			parentStepErrors[name] = stepErrors[name]
129→		}
130→	}
131→
132→	// Build steps slice sorted alphabetically by name
133→	steps := make([]perfStep, 0, len(parentStepDurations))
134→	for name, ms := range parentStepDurations {
135→		step := perfStep{
136→			Name:       name,
137→			DurationMs: ms,
138→			Error:      parentStepErrors[name],
139→		}
140→
141→		// Attach sub-steps if any, sorted by index
142→		if subs, ok := subStepDurations[name]; ok {
143→			subList := make([]perfStep, 0, len(subs))
144→			for idx, subMs := range subs {
145→				subList = append(subList, perfStep{
146→					Name:       fmt.Sprintf("%s.%d", name, idx),
147→					DurationMs: subMs,
148→					Error:      subStepErrors[name][idx],
149→				})
150→			}
151→			sort.Slice(subList, func(i, j int) bool {
152→				return subList[i].Name < subList[j].Name
153→			})
154→			step.SubSteps = subList
155→		}
156→
157→		steps = append(steps, step)
158→	}
159→	sort.Slice(steps, func(i, j int) bool {
160→		return steps[i].Name < steps[j].Name
161→	})
162→
163→	entry.Steps = steps
164→
165→	return entry
166→}
167→
168→// parseSubStepKey checks if a step name like "foo.0" is a sub-step of "foo".
169→// Returns the parent name, index, and true if it is a sub-step.
170→// A name is a sub-step if: the last segment after the final "." is a non-negative
171→// integer AND the parent name exists in allSteps.
172→func parseSubStepKey(name string, allSteps map[string]int64) (string, int, bool) {
173→	lastDot := strings.LastIndex(name, ".")
174→	if lastDot < 0 {
175→		return "", 0, false
176→	}
177→	parent := name[:lastDot]
178→	suffix := name[lastDot+1:]
179→	idx, err := strconv.Atoi(suffix)
180→	if err != nil || idx < 0 {
181→		return "", 0, false
182→	}
183→	if _, exists := allSteps[parent]; !exists {
184→		return "", 0, false
185→	}
186→	return parent, idx, true
187→}
188→
189→// collectPerfEntries reads a JSONL log file and returns the last N perf entries,
190→// ordered newest first. If hookFilter is non-empty, only entries with a matching
191→// Op field are included.
192→func collectPerfEntries(logFile string, last int, hookFilter string) ([]perfEntry, error) {
193→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
194→	if err != nil {
195→		return nil, fmt.Errorf("opening perf log: %w", err)
196→	}
197→	defer f.Close()
198→
199→	var entries []perfEntry
200→
201→	scanner := bufio.NewScanner(f)
202→	for scanner.Scan() {
203→		entry := parsePerfEntry(scanner.Text())
204→		if entry == nil {
205→			continue
206→		}
207→		if hookFilter != "" && entry.Op != hookFilter {
208→			continue
209→		}
210→		entries = append(entries, *entry)
211→	}
212→
213→	if err := scanner.Err(); err != nil {
214→		return nil, fmt.Errorf("reading perf log: %w", err)
215→	}
216→
217→	// Take the last N entries
218→	if len(entries) > last {
219→		entries = entries[len(entries)-last:]
220→	}
221→
222→	// Reverse so newest entries are first
223→	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
224→		entries[i], entries[j] = entries[j], entries[i]
225→	}
226→
227→	return entries, nil
228→}
229→
230→// renderPerfEntries writes a formatted table of perf entries to w.
231→// If entries is empty, it prints a help message about enabling perf traces.
232→func renderPerfEntries(w io.Writer, entries []perfEntry) {
233→	if len(entries) == 0 {
234→		fmt.Fprintln(w, "No perf entries found.")
235→		fmt.Fprintln(w, `Perf traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
236→		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
237→		return
238→	}
239→
240→	for i, entry := range entries {
241→		if i > 0 {
242→			fmt.Fprintln(w)
243→		}
244→
245→		// Header line: op  duration  [timestamp]
246→		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
247→		if !entry.Time.IsZero() {
248→			header += "  " + entry.Time.Format(time.RFC3339)
249→		}
250→		fmt.Fprintln(w, header)
251→		fmt.Fprintln(w)
252→
253→		if len(entry.Steps) == 0 {
254→			continue
255→		}
256→
257→		// Compute max name display width (at least len("STEP")).
258→		// Sub-steps are indented 5 extra display columns relative to parent rows
259→		// ("    " + "├─ " = 7 display cols vs "  " = 2 display cols).
260→		const subExtraIndent = 5
261→		nameWidth := len("STEP")
262→		for _, s := range entry.Steps {
263→			if len(s.Name) > nameWidth {
264→				nameWidth = len(s.Name)
265→			}
266→			for _, sub := range s.SubSteps {
267→				if needed := len(sub.Name) + subExtraIndent; needed > nameWidth {
268→					nameWidth = needed
269→				}
270→			}
271→		}
272→
273→		// Column header
274→		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
275→
276→		// Step rows
277→		for _, s := range entry.Steps {
278→			dur := fmt.Sprintf("%dms", s.DurationMs)
279→			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
280→			if s.Error {
281→				line += "  x"
282→			}
283→			fmt.Fprintln(w, line)
284→
285→			// Sub-step rows with ASCII tree connectors.
286→			// Pad manually to avoid multi-byte UTF-8 box-drawing chars
287→			// (├─, └─) breaking Go's byte-based %-*s alignment.
288→			for i, sub := range s.SubSteps {
289→				connector := "├─"
290→				if i == len(s.SubSteps)-1 {
291→					connector = "└─"
292→				}
293→				subDur := fmt.Sprintf("%dms", sub.DurationMs)
294→				pad := nameWidth - subExtraIndent - len(sub.Name)
295→				if pad < 0 {
296→					pad = 0
297→				}
298→				subLine := fmt.Sprintf("    %s %s%s  %8s", connector, sub.Name, strings.Repeat(" ", pad), subDur)
299→				if sub.Error {
300→					subLine += "  x"
301→				}
302→				fmt.Fprintln(w, subLine)
303→			}
304→		}
305→	}
306→}
