 12→const testOpPostCommit = "post-commit"
 13→
 14→func TestParsePerfEntry(t *testing.T) {
 15→	t.Parallel()
 16→
 17→	t.Run("valid perf entry", func(t *testing.T) {
 18→		t.Parallel()
 19→
 20→		line := `{"time":"2026-01-15T10:30:00.000Z","level":"DEBUG","msg":"perf","component":"perf","op":"post-commit","duration_ms":150,"error":true,"steps.load_session_ms":50,"steps.save_checkpoint_ms":80,"steps.save_checkpoint_err":true}`
 21→
 22→		entry := parsePerfEntry(line)
 23→		if entry == nil {
 24→			t.Fatal("parsePerfEntry returned nil for valid perf entry")
 25→		}
 26→
 27→		if entry.Op != testOpPostCommit {
 28→			t.Errorf("Op = %q, want %q", entry.Op, testOpPostCommit)
 29→		}
 30→		if entry.DurationMs != 150 {
 31→			t.Errorf("DurationMs = %d, want %d", entry.DurationMs, 150)
 32→		}
 33→		if !entry.Error {
 34→			t.Error("Error = false, want true")
 35→		}
 36→
 37→		expectedTime, err := time.Parse(time.RFC3339, "2026-01-15T10:30:00.000Z")
 38→		if err != nil {
 39→			t.Fatalf("failed to parse expected time: %v", err)
 40→		}
 41→		if !entry.Time.Equal(expectedTime) {
 42→			t.Errorf("Time = %v, want %v", entry.Time, expectedTime)
 43→		}
 44→
 45→		if len(entry.Steps) != 2 {
 46→			t.Fatalf("len(Steps) = %d, want 2", len(entry.Steps))
 47→		}
 48→
 49→		// Steps are sorted alphabetically by name
 50→		if entry.Steps[0].Name != "load_session" {
 51→			t.Errorf("Steps[0].Name = %q, want %q", entry.Steps[0].Name, "load_session")
 52→		}
 53→		if entry.Steps[0].DurationMs != 50 {
 54→			t.Errorf("Steps[0].DurationMs = %d, want %d", entry.Steps[0].DurationMs, 50)
 55→		}
 56→		if entry.Steps[0].Error {
 57→			t.Error("Steps[0].Error = true, want false")
 58→		}
 59→
 60→		if entry.Steps[1].Name != "save_checkpoint" {
 61→			t.Errorf("Steps[1].Name = %q, want %q", entry.Steps[1].Name, "save_checkpoint")
 62→		}
 63→		if entry.Steps[1].DurationMs != 80 {
 64→			t.Errorf("Steps[1].DurationMs = %d, want %d", entry.Steps[1].DurationMs, 80)
 65→		}
 66→		if !entry.Steps[1].Error {
 67→			t.Error("Steps[1].Error = false, want true")
 68→		}
 69→	})
 70→
 71→	t.Run("non-perf entry returns nil", func(t *testing.T) {
 72→		t.Parallel()
 73→
 74→		line := `{"time":"2026-01-15T10:30:00.000Z","level":"INFO","msg":"hook invoked","component":"lifecycle","hook":"post-commit"}`
 75→
 76→		entry := parsePerfEntry(line)
 77→		if entry != nil {
 78→			t.Errorf("parsePerfEntry returned %+v for non-perf entry, want nil", entry)
 79→		}
 80→	})
 81→
 82→	t.Run("invalid JSON returns nil", func(t *testing.T) {
 83→		t.Parallel()
 84→
 85→		entry := parsePerfEntry("this is not json at all{{{")
 86→		if entry != nil {
 87→			t.Errorf("parsePerfEntry returned %+v for invalid JSON, want nil", entry)
 88→		}
 89→	})
 90→}
