 92→func TestCollectPerfEntries(t *testing.T) {
 93→	t.Parallel()
 94→
 95→	// Fixture: 4 lines — 2 prepare-commit-msg, 1 non-perf, 1 post-commit
 96→	fixtureLines := []string{
 97→		`{"time":"2026-01-15T10:00:00Z","level":"DEBUG","msg":"perf","op":"prepare-commit-msg","duration_ms":100}`,
 98→		`{"time":"2026-01-15T10:01:00Z","level":"DEBUG","msg":"perf","op":"prepare-commit-msg","duration_ms":120}`,
 99→		`{"time":"2026-01-15T10:02:00Z","level":"INFO","msg":"hook invoked","component":"lifecycle","hook":"post-commit"}`,
100→		`{"time":"2026-01-15T10:03:00Z","level":"DEBUG","msg":"perf","op":"post-commit","duration_ms":200}`,
101→	}
102→	fixtureContent := strings.Join(fixtureLines, "\n") + "\n"
103→
104→	writeFixture := func(t *testing.T) string {
105→		t.Helper()
106→		dir := t.TempDir()
107→		p := filepath.Join(dir, "perf.jsonl")
108→		if err := os.WriteFile(p, []byte(fixtureContent), 0o644); err != nil {
109→			t.Fatalf("failed to write fixture: %v", err)
110→		}
111→		return p
112→	}
113→
114→	t.Run("last 2 entries", func(t *testing.T) {
115→		t.Parallel()
116→		logFile := writeFixture(t)
117→
118→		entries, err := collectPerfEntries(logFile, 2, "")
119→		if err != nil {
120→			t.Fatalf("collectPerfEntries returned error: %v", err)
121→		}
122→
123→		if len(entries) != 2 {
124→			t.Fatalf("got %d entries, want 2", len(entries))
125→		}
126→
127→		// Newest first: post-commit (line 4), then prepare-commit-msg (line 2)
128→		if entries[0].Op != testOpPostCommit {
129→			t.Errorf("entries[0].Op = %q, want %q", entries[0].Op, testOpPostCommit)
130→		}
131→		if entries[0].DurationMs != 200 {
132→			t.Errorf("entries[0].DurationMs = %d, want %d", entries[0].DurationMs, 200)
133→		}
134→		if entries[1].Op != "prepare-commit-msg" {
135→			t.Errorf("entries[1].Op = %q, want %q", entries[1].Op, "prepare-commit-msg")
136→		}
137→		if entries[1].DurationMs != 120 {
138→			t.Errorf("entries[1].DurationMs = %d, want %d", entries[1].DurationMs, 120)
139→		}
140→	})
141→
142→	t.Run("filter by hook type", func(t *testing.T) {
143→		t.Parallel()
144→		logFile := writeFixture(t)
145→
146→		entries, err := collectPerfEntries(logFile, 10, testOpPostCommit)
147→		if err != nil {
148→			t.Fatalf("collectPerfEntries returned error: %v", err)
149→		}
150→
151→		if len(entries) != 1 {
152→			t.Fatalf("got %d entries, want 1", len(entries))
153→		}
154→		if entries[0].Op != testOpPostCommit {
155→			t.Errorf("entries[0].Op = %q, want %q", entries[0].Op, testOpPostCommit)
156→		}
157→	})
158→
159→	t.Run("file not found", func(t *testing.T) {
160→		t.Parallel()
161→
162→		_, err := collectPerfEntries("/nonexistent/path/perf.jsonl", 10, "")
163→		if err == nil {
164→			t.Fatal("expected error for missing file, got nil")
165→		}
166→	})
167→}
