169→func TestRenderPerfEntries(t *testing.T) {
170→	t.Parallel()
171→
172→	entries := []perfEntry{
173→		{
174→			Op:         "post-commit",
175→			DurationMs: 250,
176→			Time:       time.Date(2026, 1, 15, 10, 30, 0, 0, time.UTC),
177→			Steps: []perfStep{
178→				{Name: "load_session", DurationMs: 50, Error: false},
179→				{Name: "save_checkpoint", DurationMs: 80, Error: true},
180→				{Name: "condense", DurationMs: 120, Error: false},
181→			},
182→		},
183→	}
184→
185→	var buf bytes.Buffer
186→	renderPerfEntries(&buf, entries)
187→	out := buf.String()
188→
189→	// Verify header contains op name, total duration, and timestamp
190→	if !strings.Contains(out, "post-commit") {
191→		t.Errorf("output missing op name 'post-commit':\n%s", out)
192→	}
193→	if !strings.Contains(out, "250ms") {
194→		t.Errorf("output missing total duration '250ms':\n%s", out)
195→	}
196→	if !strings.Contains(out, "2026-01-15T10:30:00Z") {
197→		t.Errorf("output missing RFC3339 timestamp:\n%s", out)
198→	}
199→
200→	// Verify step names and durations appear
201→	if !strings.Contains(out, "load_session") {
202→		t.Errorf("output missing step name 'load_session':\n%s", out)
203→	}
204→	if !strings.Contains(out, "50ms") {
205→		t.Errorf("output missing step duration '50ms':\n%s", out)
206→	}
207→	if !strings.Contains(out, "save_checkpoint") {
208→		t.Errorf("output missing step name 'save_checkpoint':\n%s", out)
209→	}
210→	if !strings.Contains(out, "80ms") {
211→		t.Errorf("output missing step duration '80ms':\n%s", out)
212→	}
213→	if !strings.Contains(out, "condense") {
214→		t.Errorf("output missing step name 'condense':\n%s", out)
215→	}
216→	if !strings.Contains(out, "120ms") {
217→		t.Errorf("output missing step duration '120ms':\n%s", out)
218→	}
219→
220→	// Verify column header
221→	if !strings.Contains(out, "STEP") {
222→		t.Errorf("output missing column header 'STEP':\n%s", out)
223→	}
224→	if !strings.Contains(out, "DURATION") {
225→		t.Errorf("output missing column header 'DURATION':\n%s", out)
226→	}
227→
228→	// Verify error marker on the errored step line
229→	lines := strings.Split(out, "\n")
230→	foundErrorMarker := false
231→	for _, line := range lines {
232→		if strings.Contains(line, "save_checkpoint") && strings.Contains(line, "x") {
233→			foundErrorMarker = true
234→			break
235→		}
236→	}
237→	if !foundErrorMarker {
238→		t.Errorf("output missing error marker 'x' on save_checkpoint line:\n%s", out)
239→	}
240→}
