242→func TestParsePerfEntry_WithSubSteps(t *testing.T) {
243→	t.Parallel()
244→
245→	line := `{"time":"2026-01-15T10:30:00Z","level":"DEBUG","msg":"perf","op":"post-commit","duration_ms":350,"steps.process_sessions_ms":300,"steps.process_sessions.0_ms":100,"steps.process_sessions.1_ms":200,"steps.process_sessions.1_err":true,"steps.cleanup_ms":50}`
246→
247→	entry := parsePerfEntry(line)
248→	if entry == nil {
249→		t.Fatal("parsePerfEntry returned nil")
250→	}
251→
252→	if len(entry.Steps) != 2 {
253→		t.Fatalf("len(Steps) = %d, want 2", len(entry.Steps))
254→	}
255→
256→	// Steps sorted alphabetically: cleanup, process_sessions
257→	if entry.Steps[0].Name != "cleanup" {
258→		t.Errorf("Steps[0].Name = %q, want %q", entry.Steps[0].Name, "cleanup")
259→	}
260→	if len(entry.Steps[0].SubSteps) != 0 {
261→		t.Errorf("Steps[0] should have no sub-steps, got %d", len(entry.Steps[0].SubSteps))
262→	}
263→
264→	ps := entry.Steps[1]
265→	if ps.Name != "process_sessions" {
266→		t.Errorf("Steps[1].Name = %q, want %q", ps.Name, "process_sessions")
267→	}
268→	if ps.DurationMs != 300 {
269→		t.Errorf("Steps[1].DurationMs = %d, want %d", ps.DurationMs, 300)
270→	}
271→	if len(ps.SubSteps) != 2 {
272→		t.Fatalf("Steps[1] should have 2 sub-steps, got %d", len(ps.SubSteps))
273→	}
274→	if ps.SubSteps[0].Name != "process_sessions.0" {
