+)
+
+func newPerfCmd() *cobra.Command {
+	var last int
+	var hookFilter string
+
+	cmd := &cobra.Command{
+		Use:   "perf",
+		Short: "Show hook performance traces",
+		Long: `Show timing information for recent hook invocations.
